WITH a AS MATERIALIZED(SELECT company_id,selection_order,anchor_ticker,cohort_sha256,membership_acceptance_sha256 FROM population_top3000_202608_202609_v1.working_accepted_companies_v1),
r AS MATERIALIZED(SELECT * FROM population_top3000_202608_202609_v1.massive_shortinterest_record_v1 WHERE archive_key='massive-archive:S02:c1ed3ed6aa5bad110f122c2459ba27f6daa14a7ac484363d4915c0fc9ddb1f88' AND raw_record->>'settlement_date'='2026-08-14'),
j AS MATERIALIZED(SELECT a.*,r.unit_key,r.source_id,r.page_number,r.source_row,r.raw_record,r.raw_record_sha256,p.point_source_state,encode(p.identity_record_sha256,'hex') identity_record_sha256,encode(p.identity_source_sha256,'hex') identity_source_sha256,p.identity_source_ordinal FROM a LEFT JOIN r ON r.raw_record->>'ticker'=a.anchor_ticker LEFT JOIN population_top3000_202608_202609_v1.d02_anchor_source_point_v2 p ON p.company_ordinal=a.selection_order AND p.session_date='2026-08-14'),
rows AS(SELECT j.selection_order,jsonb_build_object('selected_company_id',j.company_id,'selection_order',j.selection_order,'anchor_ticker',j.anchor_ticker,'settlement_date','2026-08-14','source_unit_key',j.unit_key,'source_id',j.source_id,'source_page',j.page_number,'source_row',j.source_row,'raw_record',j.raw_record,'raw_record_sha256',j.raw_record_sha256,'identity_state',CASE WHEN j.unit_key IS NULL THEN 'SOURCE_ROW_ABSENT_REPORTABILITY_UNKNOWN' WHEN j.point_source_state='VERIFIED_POINT_AND_SOURCE_LINK' THEN 'DATED_ANCHOR_COMPANY_LINK_PRODUCER_CHECKED' ELSE 'DATED_IDENTITY_UNRESOLVED' END,'identity_record_sha256',j.identity_record_sha256,'identity_source_sha256',j.identity_source_sha256,'identity_source_ordinal',j.identity_source_ordinal,'cohort_sha256',j.cohort_sha256,'membership_acceptance_sha256',j.membership_acceptance_sha256,'scheduled_publication_date',o.values_json->'scheduled_publication_date','source_published_at',o.source_published_at,'available_at',o.available_at,'historical_received_at',o.historical_received_at,'availability_policy',o.availability_policy,'original_observation_record_sha256',o.record_sha256,'family_accepted',false,'full_instrument_coverage',false,'independent_linkage_review',false) value FROM j LEFT JOIN population_top3000_202608_202609_v1.source_observation o ON o.family_id='S02' AND o.unit_key=j.unit_key AND o.release_id='top3000_companies_202608_202609_v1')
SELECT value::text row_text,encode(sha256(convert_to(value::text,'UTF8')),'hex') row_sha256 FROM rows ORDER BY selection_order;